begin;
select plan(22);
select ok(not has_table_privilege('authenticated', 'public.profiles', 'INSERT'), 'authenticated cannot insert profiles');
select ok(has_column_privilege('authenticated', 'public.profiles', 'display_name', 'UPDATE'), 'authenticated may update display_name');
select ok(not has_column_privilege('authenticated', 'public.profiles', 'is_admin', 'UPDATE'), 'authenticated cannot update is_admin');
select ok(not has_table_privilege('authenticated', 'public.scene_tokens', 'UPDATE'), 'authenticated cannot directly update tokens');
select ok(not has_table_privilege('authenticated', 'public.actors', 'UPDATE'), 'authenticated cannot directly update actors');
select ok(not has_table_privilege('authenticated', 'public.campaign_invites', 'INSERT'), 'authenticated cannot directly create invites');
select ok(not has_table_privilege('authenticated', 'public.scene_token_turn_movement', 'UPDATE'), 'authenticated cannot directly rewrite movement');
select ok(not has_schema_privilege('anon', 'private', 'USAGE') and not has_schema_privilege('authenticated', 'private', 'USAGE'), 'internal schema is not exposed through Supabase API roles');
select ok(not has_table_privilege('anon', 'private.image_generation_limits', 'SELECT') and not has_table_privilege('authenticated', 'private.image_generation_limits', 'SELECT') and not has_table_privilege('service_role', 'private.image_generation_limits', 'SELECT'), 'image quota rows are not exposed through Supabase API roles');
select ok(not exists (select 1 from pg_policies where schemaname='public' and tablename='notes' and cmd='ALL'), 'notes no longer use a broad FOR ALL policy');
select ok((select count(*)=3 from pg_policies where schemaname='public' and tablename='notes' and policyname in ('notes_author_insert','notes_author_update','notes_author_delete')), 'notes writes remain covered by explicit insert/update/delete policies');
select ok(not exists (select 1 from pg_policies where schemaname='public' and tablename='library_item_permissions' and policyname='campaign members read item permissions'), 'players cannot enumerate other players item permissions');
select ok((select qual like '%gm%' from pg_policies where schemaname='public' and tablename='library_item_permissions' and policyname='campaign gms manage item permissions' and cmd='ALL'), 'GM-only item permission policy remains the sole read/write policy');
select ok((select qual like '%library_item_permissions%' from pg_policies where schemaname='public' and tablename='notes' and policyname='notes_member_select'), 'handout reads enforce per-player permissions');
select ok((select qual like '%library_item_permissions%' from pg_policies where schemaname='public' and tablename='scene_presentations' and policyname='campaign members can read permitted presentations'), 'presentation reads enforce per-player permissions');
select ok((select qual like '%ambient_audio_enabled%' and qual like '%ambient_effect_enabled%' and qual like '%library_item_permissions%' from pg_policies where schemaname='storage' and tablename='objects' and policyname='campaign members read permitted assets'), 'Storage reads enforce media permissions, active music and active effects');
select ok((select count(*) = 6 from information_schema.columns where table_schema='public' and table_name='scenes' and column_name like 'ambient_effect_%'), 'sound effects have independent persisted playback state');
select ok((select relrowsecurity from pg_class where oid='public.overlay_pairing_codes'::regclass), 'OBS pairing codes have RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.overlay_access_sessions'::regclass), 'OBS access grants have RLS enabled');
select ok(not has_table_privilege('anon','public.overlay_pairing_codes','SELECT') and not has_table_privilege('authenticated','public.overlay_pairing_codes','SELECT') and not has_table_privilege('anon','public.overlay_access_sessions','SELECT') and not has_table_privilege('authenticated','public.overlay_access_sessions','SELECT'), 'pairing secrets are not exposed to Data API roles');
select ok(has_trigger('public', 'game_events', 'game_events_campaign_realtime'), 'persisted campaign events publish realtime notifications');
select ok(not has_function_privilege('anon', 'public.notify_campaign_game_event()', 'EXECUTE') and not has_function_privilege('authenticated', 'public.notify_campaign_game_event()', 'EXECUTE'), 'campaign event notification function is not callable from Data API roles');
select * from finish();
rollback;
